    tags: ["inflasi", "gaji", "dinar", "1971", "sejarah"],
    hook: "Pendedahan Sejarah Kewangan Gelap",
    teks: `Duit kertas dalam dompet anda tu... sebenarnya langsung tak ada nilai sejak 15 Ogos 1971!

Ramai ingat duit kertas adalah wang sebenar, padahal ia cuma kepingan kertas yang nilainya sedang dirompak secara senyap setiap hari!

Tahu tak, sebelum tahun 1971, setiap wang kertas yang dicetak wajib disandarkan pada emas fizikal di dalam bilik kebal. Duit kertas asalnya hanyalah baucar tuntutan emas.

Tapi pada 15 Ogos 1971, Presiden Amerika batalkan sandaran tu secara sepihak! Sejak hari tu, wang kertas boleh dicetak sesuka hati tanpa sandaran apa-apa aset... dan setiap kali mesin cetak berjalan, kuasa beli duit gaji kita makin menjunam dimakan inflasi.

Tapi tengok apa jadi pada emas.

1,400 tahun lepas pada zaman Nabi, satu keping dinar emas boleh beli seekor kambing. Hari ini, selepas lebih seribu tahun... satu dinar masih mampu beli seekor kambing yang sama! Kuasa belinya tak pernah luput.

Sebelum nilai simpanan tunai anda terus cair, drop di komen: anda pernah tahu tak tentang peristiwa 15 Ogos 1971 ni?

Sebab bila anda tukar duit kertas kepada emas, anda sebenarnya sedang menukar baucar kepada mata wang yang...

Hakiki!`
